refentry.refsect1:
&reftitle.parameters;




   column



      La colonna del set di risultati, indicizzata a partire da 0.

  &reftitle.examples;



    Recupero dei metadati di una colonna


     L'esempio seguente mostra i risultati del recupero dei metadati di una
     singola colonna generata da una funzione (COUNT) in un driver PDO_SQLITE.



<?php
$select = $DB->query('SELECT COUNT(*) FROM fruit');
$meta = $select->getColumnMeta(0);
var_dump($meta);
?>


    &example.outputs;


array(6) {
  ["native_type"]=>
  string(7) "integer"
  ["flags"]=>
  array(0) {
  }
  ["name"]=>
  string(8) "COUNT(*)"
  ["len"]=>
  int(-1)
  ["precision"]=>
  int(0)
  ["pdo_type"]=>
  int(2)
}
